import { themeVars } from "@/components/cursare/foundation/model"
import { ContentCoverMedia, LearnerRoot } from "@/components/cursare/foundation/runtime"
import { Button } from "@/components/cursare/ui/button"
import { Progress, ProgressIndicator, ProgressTrack } from "@/components/cursare/ui/progress"
import { ArrowRight, Award, Check, Library } from "lucide-react"
import type { LearnerCourseProjection, LearnerHomeProjection } from "./study-projections"

export interface LearnerHomeMessages {
  resumeHeading: string
  activeHeading: string
  completedHeading: string
  continueLabel: string
  reviewLabel: string
  certificateLabel: string
  completedLabel: string
  progressLabel: (course: LearnerCourseProjection) => string
  emptyTitle: string
  emptyDescription: string
}

export interface LearnerHomeProps {
  projection: LearnerHomeProjection<LearnerCourseProjection>
  messages: LearnerHomeMessages
  emptyAction?: React.ReactNode
}

function CourseCover({
  course,
  priority = false,
}: {
  course: LearnerCourseProjection
  priority?: boolean
}) {
  return (
    <ContentCoverMedia
      src={course.coverImage}
      width={960}
      height={600}
      loading={priority ? "eager" : "lazy"}
      className="size-full"
    />
  )
}

function CourseProgress({ course, label }: { course: LearnerCourseProjection; label: string }) {
  return (
    <div className="learner-home-progress">
      <Progress value={course.percent} aria-label={label}>
        <ProgressTrack className="h-1.5">
          <ProgressIndicator />
        </ProgressTrack>
      </Progress>
      <span>{label}</span>
    </div>
  )
}

export function LearnerHome({ projection, messages, emptyAction }: LearnerHomeProps) {
  const { primary, active, completed } = projection
  if (!primary && completed.length === 0) {
    return (
      <LearnerRoot
        as="section"
        contractKey="blocks.learner-home"
        className="learner-home-empty"
        aria-labelledby="learner-home-empty-title"
      >
        <Library aria-hidden />
        <h2 id="learner-home-empty-title">{messages.emptyTitle}</h2>
        <p>{messages.emptyDescription}</p>
        {emptyAction}
      </LearnerRoot>
    )
  }

  return (
    <LearnerRoot contractKey="blocks.learner-home" className="learner-home-flow">
      {primary ? (
        <section aria-labelledby="learner-home-resume-title">
          <p className="learner-home-eyebrow">{messages.resumeHeading}</p>
          <article
            className="learner-home-primary"
            style={themeVars(primary.theme)}
            data-testid="learner-home-primary"
          >
            <div className="learner-home-primary-cover">
              <CourseCover course={primary} priority />
            </div>
            <div className="learner-home-primary-copy">
              <p>{primary.publisher}</p>
              <h2 id="learner-home-resume-title">{primary.title}</h2>
              {primary.description ? <p>{primary.description}</p> : null}
              <CourseProgress course={primary} label={messages.progressLabel(primary)} />
              <Button render={<a href={primary.resumeHref} />}>
                {messages.continueLabel} <ArrowRight />
              </Button>
            </div>
          </article>
        </section>
      ) : null}

      {active.length > 0 ? (
        <section aria-labelledby="learner-home-active-title">
          <h2 id="learner-home-active-title" className="learner-home-section-title">
            {messages.activeHeading}
          </h2>
          <div className="learner-home-active-list">
            {active.map((course) => (
              <article
                key={course.key}
                className="learner-home-active-course"
                style={themeVars(course.theme)}
              >
                <div className="learner-home-active-cover">
                  <CourseCover course={course} />
                </div>
                <div className="min-w-0 flex-1">
                  <p className="learner-home-course-publisher">{course.publisher}</p>
                  <h3>{course.title}</h3>
                  <CourseProgress course={course} label={messages.progressLabel(course)} />
                </div>
                <Button variant="outline" render={<a href={course.resumeHref} />}>
                  {messages.continueLabel}
                </Button>
              </article>
            ))}
          </div>
        </section>
      ) : null}

      {completed.length > 0 ? (
        <section aria-labelledby="learner-home-completed-title">
          <h2 id="learner-home-completed-title" className="learner-home-section-title">
            {messages.completedHeading}
          </h2>
          <div className="learner-home-completed-list">
            {completed.map((course) => (
              <article key={course.key} className="learner-home-completed-course">
                <span className="learner-home-complete-mark">
                  <Check aria-hidden />
                </span>
                <div className="min-w-0 flex-1">
                  <p>{messages.completedLabel}</p>
                  <h3>{course.title}</h3>
                  <span>{course.publisher}</span>
                </div>
                <div className="flex flex-wrap gap-2">
                  <Button variant="secondary" render={<a href={course.courseHomeHref} />}>
                    {messages.reviewLabel}
                  </Button>
                  {course.certificateHref ? (
                    <Button variant="outline" render={<a href={course.certificateHref} />}>
                      <Award /> {messages.certificateLabel}
                    </Button>
                  ) : null}
                </div>
              </article>
            ))}
          </div>
        </section>
      ) : null}
    </LearnerRoot>
  )
}

import {
  type ContentNode,
  learnerAnchorId,
  type ParsedContentDocument,
} from "@/components/cursare/foundation/model"
export interface LearnerCourseProjection {
  key: string
  title: string
  publisher: string
  description: string | null
  coverImage: string | null
  theme?: string | null
  done: number
  total: number
  percent: number
  completed: boolean
  resumeHref: string
  courseHomeHref: string
  certificateHref?: string | null
}

export interface LearnerHomeProjection<T extends { completed: boolean }> {
  primary: T | null
  active: T[]
  completed: T[]
}

export function projectLearnerHome<T extends { completed: boolean }>(
  courses: readonly T[],
): LearnerHomeProjection<T> {
  const active = courses.filter((course) => !course.completed)
  return {
    primary: active[0] ?? null,
    active: active.slice(1),
    completed: courses.filter((course) => course.completed),
  }
}

export type CurriculumItemKind = "section" | "reference"
export type CurriculumItemState = "completed" | "current" | "available" | "locked"

export interface CurriculumStepSource {
  kind: CurriculumItemKind
  id: string
  title: string
  done: boolean
  available: boolean
  current: boolean
  locked: boolean
  lockReason: "drip" | "prerequisite" | null
  unlockAt: number | null
  routeSegment: string | null
}

export interface CurriculumJourneyItem extends CurriculumStepSource {
  state: CurriculumItemState
  href: string | null
  position: number
}

export function projectCurriculumJourney(
  steps: readonly CurriculumStepSource[],
  destinationFor: (step: CurriculumStepSource) => string | null,
): CurriculumJourneyItem[] {
  const declaredCurrent = steps.findIndex((step) => step.current && !step.done && !step.locked)
  const nextAvailable = steps.findIndex((step) => step.available && !step.done && !step.locked)
  const currentIndex = declaredCurrent >= 0 ? declaredCurrent : nextAvailable

  return steps.map((step, index) => {
    const state: CurriculumItemState = step.done
      ? "completed"
      : step.locked || !step.available
        ? "locked"
        : index === currentIndex
          ? "current"
          : "available"
    const reachable = !step.locked && (step.available || step.done)
    return {
      ...step,
      current: state === "current",
      state,
      href: reachable ? destinationFor(step) : null,
      position: index + 1,
    }
  })
}

export type StudyResourceKind = "download" | "external"

export interface StudyResource {
  key: string
  kind: StudyResourceKind
  label: string
  href: string
  size: number | null
  mime: string | null
  activityId?: string | null
  sectionId?: string
}

function isSafeDownloadUrl(value: unknown): value is string {
  if (typeof value !== "string" || value.length === 0 || value.length > 2_048) return false
  if (value.startsWith("/") && !value.startsWith("//")) return true
  try {
    return new URL(value).protocol === "https:"
  } catch {
    return false
  }
}

function isSafeExternalUrl(value: unknown): value is string {
  if (typeof value !== "string" || value.length === 0 || value.length > 2_048) return false
  try {
    return ["https:", "http:"].includes(new URL(value).protocol)
  } catch {
    return false
  }
}

function textOf(node: ContentNode): string {
  return node.text ?? (node.content ?? []).map(textOf).join("")
}

// Only from the already-revealed document the host supplied.
export function extractStudyResources(doc: ParsedContentDocument): StudyResource[] {
  const resources: StudyResource[] = []
  const seen = new Set<string>()
  let sectionId = "section:0"

  const add = (resource: StudyResource) => {
    const identity = `${resource.kind}:${resource.href}`
    if (seen.has(identity)) return
    seen.add(identity)
    resources.push(resource)
  }

  const visit = (node: ContentNode, inheritedActivityId: string | null = null) => {
    const ownActivityId = learnerAnchorId(node)
    if (node.type === "heading" && ownActivityId) sectionId = ownActivityId
    const activityId = ownActivityId ?? inheritedActivityId
    if (node.type === "fileAttachment") {
      const href = node.attrs?.url
      if (isSafeDownloadUrl(href)) {
        const name =
          typeof node.attrs?.name === "string" && node.attrs.name.trim()
            ? node.attrs.name.trim()
            : "Download"
        add({
          key: `download:${href}`,
          kind: "download",
          label: name,
          href,
          size: typeof node.attrs?.size === "number" ? node.attrs.size : null,
          mime: typeof node.attrs?.mime === "string" ? node.attrs.mime : null,
          activityId,
          sectionId,
        })
      }
    }

    for (const mark of node.marks ?? []) {
      const href = mark.type === "link" ? mark.attrs?.href : null
      if (!isSafeExternalUrl(href)) continue
      add({
        key: `external:${href}`,
        kind: "external",
        label: textOf(node).trim() || new URL(href).hostname,
        href,
        size: null,
        mime: null,
        activityId,
        sectionId,
      })
    }

    for (const child of node.content ?? []) visit(child, activityId)
  }

  visit(doc)
  return resources
}

/* Shared white-label surface styles. Brand comes exclusively from host tokens. */

.fallback-panel {
  background-color: color-mix(
    in oklab,
    var(--fallback-tint, var(--fx-a, var(--color-zinc-400))) 9%,
    var(--color-zinc-100)
  );
  background-image: radial-gradient(var(--color-border) 1px, transparent 1px);
  background-size: 20px 20px;
  color: var(--color-foreground);
}

.dark .fallback-panel {
  background-color: color-mix(
    in oklab,
    var(--fallback-tint, var(--fx-a, var(--color-zinc-400))) 12%,
    var(--color-zinc-900)
  );
}

.content-hero-page .content-prose .content-cover {
  display: none;
}

.learner-course-shell,
.learner-course-storefront {
  min-height: 100dvh;
}

.learner-course-shell {
  background: var(--background);
}

.learner-course-storefront {
  background: var(--course-canvas, var(--background));
}

.course-cover-theme {
  background: linear-gradient(
    110deg,
    color-mix(in oklab, var(--foreground) 5%, transparent),
    transparent 42%,
    color-mix(in oklab, var(--foreground) 3%, transparent)
  );
}

.course-cover-fade {
  background: linear-gradient(to bottom, transparent, var(--course-canvas, var(--background)));
}

.learner-course-intro::before {
  display: none;
  content: none;
}

.learner-course-shell > main {
  --course-canvas: var(--background);
  --course-canvas-strong: color-mix(in oklab, var(--background) 96%, var(--foreground) 4%);
  --course-selection: color-mix(in oklab, var(--background) 93%, var(--foreground) 7%);
}

.learner-course-shell .content-editor[data-mode="reader"] {
  --course-canvas: var(--background);
  --course-canvas-strong: color-mix(in oklab, var(--background) 96%, var(--foreground) 4%);
  --course-selection: color-mix(in oklab, var(--background) 93%, var(--foreground) 7%);
}

.learner-reader-with-shell .content-prose > h1[data-type="title"],
.learner-reader-with-shell .content-prose > p[data-type="description"] {
  display: none;
}

.learner-reader-with-shell .content-prose > :is(h1, h2, h3)[data-block-id] {
  scroll-margin-top: 7.5rem;
}

.learner-reader-with-shell .content-prose > h2[data-block-id] {
  margin-top: clamp(1.5rem, 2vw, 2rem);
  margin-bottom: 1.15rem;
  font-size: clamp(1.55rem, 2vw, 1.85rem);
  font-weight: 650;
  line-height: 1.18;
  letter-spacing: -0.025em;
}

@media (max-width: 640px) {
  .learner-reader-with-shell .content-prose > h2[data-block-id] {
    margin-bottom: 0.9rem;
    font-size: 1.5rem;
  }
}

.learner-course-shell {
  --learner-font-family: var(--font-cal-sans, ui-sans-serif), system-ui, sans-serif;
  --learner-prose-geometry: 0;
  --learner-control-geometry: 0;
  --learner-heading-geometry: 32;
  --learner-reading-measure: 72ch;
  font-family: var(--learner-font-family);
  font-variation-settings: "GEOM" var(--learner-prose-geometry);
}

.learner-course-shell :is(h1, h2, h3, h4, h5, h6) {
  font-family: var(--learner-font-family);
  font-variation-settings: "GEOM" var(--learner-heading-geometry);
}

.learner-course-shell :is(button, input, textarea, select, [data-slot="button"]) {
  font-family: var(--learner-font-family);
  font-variation-settings: "GEOM" var(--learner-control-geometry);
}

.learner-reader-with-shell .content-editor[data-mode="reader"] .content-prose {
  font-family: var(--learner-font-family);
  font-variation-settings: "GEOM" var(--learner-prose-geometry);
}

.learner-reader-with-shell
  .content-editor[data-mode="reader"]
  .content-prose
  > :is(p, ul, ol, blockquote) {
  width: min(100%, var(--learner-reading-measure));
  max-width: var(--learner-reading-measure);
}

/* Learner orientation keeps one editorial hierarchy: imagery establishes
   identity, while progress and actions remain semantic product controls. */
.learner-home-flow {
  display: flex;
  flex-direction: column;
  gap: clamp(2.5rem, 6vw, 5rem);
}

.learner-home-eyebrow {
  margin-bottom: 0.75rem;
  color: var(--muted-foreground);
  font-weight: 600;
  font-size: var(--learner-label-size);
  line-height: var(--learner-label-line);
  letter-spacing: normal;
  text-transform: none;
}

.learner-home-primary {
  display: grid;
  overflow: hidden;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  border-radius: 1.25rem;
  background: var(--background);
}

.learner-home-primary-cover,
.learner-course-home-cover {
  position: relative;
  min-height: 12rem;
  aspect-ratio: 16 / 10;
  overflow: hidden;
  background: var(--muted);
}

.learner-home-primary-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  padding: clamp(1.5rem, 4vw, 3.25rem);
}

.learner-home-primary-copy > p:first-child,
.learner-home-course-publisher,
.learner-course-home-publisher {
  color: var(--muted-foreground);
  font-size: 0.75rem;
}

.learner-home-primary-copy h2 {
  max-width: 22ch;
  margin-top: 0.35rem;
  font-family: var(--font-cal-sans, ui-sans-serif), system-ui, sans-serif;
  font-size: clamp(1.8rem, 5vw, 3.25rem);
  line-height: 1.02;
  letter-spacing: -0.04em;
  overflow-wrap: anywhere;
}

.learner-home-primary-copy h2 + p {
  display: -webkit-box;
  max-width: 58ch;
  margin-top: 1rem;
  overflow: hidden;
  color: var(--muted-foreground);
  line-height: 1.65;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}

.learner-home-progress {
  width: min(100%, 30rem);
  margin-block: 1.5rem;
}

.learner-home-progress > span {
  display: block;
  margin-top: 0.5rem;
  color: var(--muted-foreground);
  font-size: 0.75rem;
}

.learner-home-section-title,
.learner-journey-title {
  margin-bottom: 1rem;
  font-family: var(--font-cal-sans, ui-sans-serif), system-ui, sans-serif;
  font-weight: 600;
  font-size: clamp(1.25rem, 3vw, 1.75rem);
  letter-spacing: -0.025em;
}

.learner-home-active-list,
.learner-home-completed-list {
  display: flex;
  flex-direction: column;
  border-top: 1px solid var(--border);
}

.learner-home-active-course,
.learner-home-completed-course {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 1rem;
  padding-block: 1rem;
  border-bottom: 1px solid var(--border);
}

.learner-home-active-cover {
  width: 6.5rem;
  aspect-ratio: 16 / 10;
  flex: none;
  overflow: hidden;
  border-radius: 0.5rem;
  background: var(--muted);
}

.learner-home-active-course h3,
.learner-home-completed-course h3 {
  font-weight: 600;
  overflow-wrap: anywhere;
}

.learner-home-active-course .learner-home-progress {
  max-width: 20rem;
  margin-block: 0.65rem 0;
}

.learner-home-completed-course > div > p,
.learner-home-completed-course > div > span {
  color: var(--muted-foreground);
  font-size: 0.75rem;
}

.learner-home-complete-mark {
  display: grid;
  width: 2rem;
  height: 2rem;
  flex: none;
  place-items: center;
  border: 1px solid var(--border);
  border-radius: 999px;
}

.learner-home-complete-mark svg {
  width: 0.9rem;
  height: 0.9rem;
}

button.learner-completion-marker {
  width: 2.75rem;
  height: 2.75rem;
  border-color: transparent;
  background: transparent;
  box-shadow: none;
}

button.learner-completion-marker::before {
  inset: 0.8125rem;
  border: 1px solid var(--input);
  background: var(--background);
}

button.learner-completion-marker > [data-slot="checkbox-indicator"] {
  inset: 0.8125rem;
}

.learner-home-empty {
  display: grid;
  min-height: 22rem;
  place-items: center;
  align-content: center;
  padding: 2rem;
  border: 1px solid var(--border);
  border-radius: 1rem;
  text-align: center;
}

.learner-home-empty > svg {
  width: 2rem;
  height: 2rem;
  margin-bottom: 1rem;
  color: var(--muted-foreground);
}

.learner-home-empty h2 {
  font-family: var(--font-cal-sans, ui-sans-serif), system-ui, sans-serif;
  font-weight: 600;
  font-size: 1.5rem;
}

.learner-home-empty > p:last-of-type {
  max-width: 34rem;
  margin-block: 0.5rem 1.25rem;
  color: var(--muted-foreground);
}

.learner-course-home {
  min-height: 100dvh;
  padding: clamp(1rem, 4vw, 3.5rem);
  background: var(--background);
}

.learner-course-home-hero,
.learner-course-home-grid {
  width: min(100%, 80rem);
  margin-inline: auto;
}

.learner-course-home-hero {
  display: grid;
  overflow: hidden;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  border-radius: 1.25rem;
}

.learner-course-home-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  padding: clamp(1.5rem, 4vw, 3.5rem);
}

.learner-course-home-copy h1 {
  max-width: 20ch;
  margin-top: 0.45rem;
  font-family: var(--font-cal-sans, ui-sans-serif), system-ui, sans-serif;
  font-weight: 600;
  font-size: clamp(2rem, 5vw, 4rem);
  line-height: 0.98;
  letter-spacing: -0.045em;
  overflow-wrap: anywhere;
}

.learner-course-home-description {
  max-width: 58ch;
  margin-top: 1rem;
  color: var(--muted-foreground);
  font-size: 1rem;
  line-height: 1.65;
}

.learner-course-home-progress {
  width: min(100%, 32rem);
  margin-top: 1.75rem;
}

.learner-course-home-progress > div {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.5rem;
  color: var(--muted-foreground);
  font-size: 0.75rem;
}

.learner-course-home-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.625rem 1rem;
  margin-top: 1.5rem;
}

.learner-course-home-primary-action,
.learner-course-home-secondary-actions {
  display: flex;
  align-items: center;
}

.learner-course-home-secondary-actions {
  flex-wrap: wrap;
  gap: 0.25rem;
}

.learner-course-home-grid {
  display: grid;
  gap: clamp(2rem, 5vw, 4rem);
  padding-block: clamp(2.5rem, 6vw, 5rem);
}

.learner-journey-list {
  display: flex;
  flex-direction: column;
  border-top: 1px solid var(--border);
}

.learner-journey-list > li {
  border-bottom: 1px solid var(--border);
}

.learner-journey-item {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.9rem;
  padding: 1rem 0.75rem;
}

.learner-journey-link {
  border-radius: 0.35rem;
  outline: none;
  transition: background-color 120ms ease;
}

.learner-journey-link:hover {
  background: color-mix(in oklab, var(--foreground) 4%, transparent);
}

.learner-journey-link:focus-visible {
  box-shadow: 0 0 0 2px var(--ring);
}

.learner-journey-icon {
  display: grid;
  width: 2rem;
  height: 2rem;
  flex: none;
  place-items: center;
  border: 1px solid var(--border);
  border-radius: 999px;
}

.learner-journey-icon svg {
  width: 0.9rem;
  height: 0.9rem;
}

[data-journey-state="current"] .learner-journey-icon {
  border-color: var(--course-accent, var(--primary));
  background: var(--course-accent, var(--primary));
  color: var(--primary-foreground);
}

[data-journey-state="locked"] .learner-journey-item {
  color: var(--muted-foreground);
}

.learner-journey-copy {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
}

.learner-journey-name {
  font-weight: 500;
}

.learner-journey-meta {
  margin-top: 0.2rem;
  color: var(--muted-foreground);
  font-size: 0.75rem;
}

.learner-course-home-cohort {
  align-self: start;
  padding: 1.25rem;
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  background: color-mix(in oklab, var(--background) 97%, var(--foreground) 3%);
}

